/**
 * Card (spec/02 §3.4) for settings or figures: level 1 (D46), bg with the 2 dp ink layer line, radius container,
 * 16 dp inside, parts 8 dp apart: [title] (title), [text] (body textMuted), [content], then [actions] (8 dp more,
 * wrapping). [onClick] = the whole card is the target: the title gets the link underline, hover and pressed fills,
 * no ripple, the focus ring outside. Never tinted, never a shadow, never for list items.
 */
@Composable
fun SbCard(
    modifier: Modifier = Modifier,
    title: String? = null,
    text: String? = null,
    onClick: (() -> Unit)? = null,
    actions: (@Composable () -> Unit)? = null,
    content: (@Composable () -> Unit)? = null,
) {
    val c = SebaroTheme.colors
    val t = SebaroTheme.tokens
    val ty = SebaroTheme.typography
    val level = t.elevation.level1
    SbCardFrame(onClick, level.borderWidth, level.borderColor, modifier) {
        if (title != null) {
            if (onClick != null) SbCardLinkTitle(title) else Text(title, style = ty.title, color = c.text)
        }
        if (text != null) Text(text, style = ty.body, color = c.textMuted)
        content?.invoke()
        if (actions != null) {
            SbFlowRow(
                Modifier.padding(top = t.space.s2),
                horizontalArrangement = Arrangement.spacedBy(t.space.s2),
                verticalArrangement = Arrangement.spacedBy(t.space.s2),
            ) { actions() }
        }
    }
}

/**
 * Item card (spec/02 §3.4, D83 (3)): one of many cards of one kind (board, collection): a 1 dp borderStrong edge,
 * radius container, 16 dp inside, [title] in title, [text] in body textMuted. [current] = the 3 dp accent place line
 * at its start (only one card is current; TalkBack „aktuell“). [onClick] as SbCard, without the underline.
 */
@Composable
fun SbItemCard(
    title: String,
    modifier: Modifier = Modifier,
    text: String? = null,
    current: Boolean = false,
    onClick: (() -> Unit)? = null,
) {
    val c = SebaroTheme.colors
    val t = SebaroTheme.tokens
    val ty = SebaroTheme.typography
    val word = sbMessages().itemCurrent
    SbCardFrame(
        onClick,
        t.borderWidth.hairline,
        c.borderStrong,
        modifier.then(if (current) Modifier.semantics { stateDescription = word } else Modifier),
        place = current,
    ) {
        Text(title, style = ty.title, color = c.text)
        if (text != null) Text(text, style = ty.body, color = c.textMuted)
    }
}

/** The frame of both cards: edge, radius 12, 16 dp inside, 8 dp between parts; the target and the place line. */
@Composable
private fun SbCardFrame(
    onClick: (() -> Unit)?,
    edgeWidth: Dp,
    edgeColor: Color,
    modifier: Modifier,
    place: Boolean = false,
    content: @Composable () -> Unit,
) {
    val c = SebaroTheme.colors
    val t = SebaroTheme.tokens
    val shape = t.shapes.container
    val interaction = remember { MutableInteractionSource() }
    val pressed by interaction.collectIsPressedAsState()
    val hovered by interaction.collectIsHoveredAsState()
    val fill = when {
        onClick != null && pressed -> c.pressedFill
        onClick != null && hovered -> c.hoverFill
        else -> c.bg
    }
    val target = if (onClick == null) {
        Modifier.semantics(mergeDescendants = true) { }
    } else {
        Modifier.clickable(interactionSource = interaction, indication = null, onClick = onClick)
    }
    Column(
        modifier
            .fillMaxWidth()
            .then(if (onClick != null) Modifier.sbFocusRing(interaction, t.radius.container) else Modifier)
            .clip(shape)
            .drawWithContent {
                drawContent()
                // the place line at the start, inside the rounded edge (the web's border-inline-start)
                if (place) {
                    val w = t.borderWidth.strong.toPx()
                    val x = if (layoutDirection == LayoutDirection.Rtl) size.width - w else 0f
                    drawRect(c.accent, Offset(x, 0f), Size(w, size.height))
                }
            }
            .background(fill, shape)
            .border(edgeWidth, edgeColor, shape)
            .then(target)
            .padding(t.spacing.insetContainer),
        verticalArrangement = Arrangement.spacedBy(t.space.s2),
    ) { content() }
}

/** The title of a card that is a link: title, the 2 dp link underline 0.2 em under every line (D52). */
@Composable
private fun SbCardLinkTitle(title: String) {
    val c = SebaroTheme.colors
    val style = SebaroTheme.typography.title
    val width = SebaroTheme.tokens.x.linkUnderlineWidth
    var layout by remember { mutableStateOf<TextLayoutResult?>(null) }
    Text(
        title,
        Modifier.drawBehind {
            val l = layout ?: return@drawBehind
            val w = width.toPx()
            val gap = style.fontSize.toPx() * 0.2f
            for (line in 0 until l.lineCount) {
                val y = l.getLineBaseline(line) + gap
                drawLine(c.link, Offset(l.getLineLeft(line), y), Offset(l.getLineRight(line), y), w)
            }
        },
        style = style,
        color = c.text,
        onTextLayout = { layout = it },
    )
}
